import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"漂流钓鱼指南","description":"了解科技空岛的专用漂流鱼竿、空中抛竿、六级独立奖池和鱼竿成长。","frontmatter":{"title":"漂流钓鱼指南","description":"了解科技空岛的专用漂流鱼竿、空中抛竿、六级独立奖池和鱼竿成长。"},"headers":[],"relativePath":"skyblock/fishing.md","filePath":"skyblock/fishing.md"}`),a={name:`skyblock/fishing.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="向虚空抛竿-漂流钓鱼指南" tabindex="-1">向虚空抛竿：漂流钓鱼指南 <a class="header-anchor" href="#向虚空抛竿-漂流钓鱼指南" aria-label="Permalink to “向虚空抛竿：漂流钓鱼指南”">​</a></h1><p>空岛缺少现成的土地和种源，漂流钓鱼为它们提供了另一种来路。拿上专用鱼竿，在岛边留一处安全的站位，就可以开始尝试。</p><h2 id="和普通水上钓鱼有什么不同" tabindex="-1">和普通水上钓鱼有什么不同？ <a class="header-anchor" href="#和普通水上钓鱼有什么不同" aria-label="Permalink to “和普通水上钓鱼有什么不同？”">​</a></h2><p>普通钓鱼把浮漂投入水中；科技空岛的漂流玩法是在<strong>足够空旷的空间向空气抛竿</strong>，从服务器为鱼竿等级配置的奖池中获得材料和种源。</p><p>必须使用专用漂流鱼竿。系统会识别鱼竿本身的标记，普通鱼竿或只在铁砧上改名的鱼竿都不能替代。</p><h2 id="第一次尝试" tabindex="-1">第一次尝试 <a class="header-anchor" href="#第一次尝试" aria-label="Permalink to “第一次尝试”">​</a></h2><ol><li>按当前服内说明取得专用漂流鱼竿，并确认它的等级。初始发放方式尚待服主补充。</li><li>找一处空旷、安全的抛竿位置，确认自己不会走落虚空。</li><li>手持专用竿，向空气抛竿，等待咬钩后收竿。</li><li>成功钓取时，从该等级奖池获得一种物品；数量在表内范围随机。</li></ol><p>如果没成功，先检查鱼竿是否正确、抛竿空间是否足够，再查看当前服内说明。使用 XPlus 的玩家可继续看 <a href="./../guides/xplus-autofish.html">自动钓鱼参考设置</a>。</p><h2 id="六根鱼竿-各有适合的材料" tabindex="-1">六根鱼竿，各有适合的材料 <a class="header-anchor" href="#六根鱼竿-各有适合的材料" aria-label="Permalink to “六根鱼竿，各有适合的材料”">​</a></h2><table tabindex="0"><thead><tr><th>等级</th><th>鱼竿</th><th>主要用途</th><th>完整掉落</th></tr></thead><tbody><tr><td>1</td><td>拾荒竿</td><td>开局基础材料与种源</td><td><a href="./fishing-rewards.html#tier-1">查看 1 级</a></td></tr><tr><td>2</td><td>培育竿</td><td>扩展农业、作物与生态种源</td><td><a href="./fishing-rewards.html#tier-2">查看 2 级</a></td></tr><tr><td>3</td><td>拓荒竿</td><td>灵魂材料与下界植物种源</td><td><a href="./fishing-rewards.html#tier-3">查看 3 级</a></td></tr><tr><td>4</td><td>匠作竿</td><td>海洋资源、紫水晶与装饰材料</td><td><a href="./fishing-rewards.html#tier-4">查看 4 级</a></td></tr><tr><td>5</td><td>远航竿</td><td>末地种植材料与稀有生态资源</td><td><a href="./fishing-rewards.html#tier-5">查看 5 级</a></td></tr><tr><td>6</td><td>星海竿</td><td>提高部分单次获取数量，加入稀有收藏品</td><td><a href="./fishing-rewards.html#tier-6">查看 6 级</a></td></tr></tbody></table><p><strong>六级使用独立奖池，高级竿不自动继承低级奖池。</strong> 比如想钓橡树树苗，应先查看包含它的等级，而不是只用手里等级最高的鱼竿。</p><h2 id="升级之前-先看清目标" tabindex="-1">升级之前，先看清目标 <a class="header-anchor" href="#升级之前-先看清目标" aria-label="Permalink to “升级之前，先看清目标”">​</a></h2><p>岛屿任务中的升级芯片可以参与鱼竿成长，升阶还需要前一级鱼竿与对应材料，详见 <a href="./resources.html#rods">岛屿任务与鱼竿成长</a>。</p><p>六级奖池已配置，但第六级鱼竿的完整获取与升阶流程尚待确认。奖池有末地材料，也不代表独立末地岛已开放。</p><p>继续阅读：<a href="./fishing-rewards.html">六级完整概率表</a> · <a href="./../guides/xplus-autofish.html">XPlus 设置</a> · <a href="./../guides/">返回知识库</a></p>`,15)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};